-- Proposed additive commerce schema.
-- Review this SQL before applying it. It has not been executed.
-- Prisma cuid() IDs are generated by Prisma clients, so these columns have no SQL default.
-- Order item snapshots and the order total must be calculated server-side and
-- inserted in one Prisma transaction; cross-row order sums are not CHECKable.
-- Refund representation is full-refund only: PaymentStatus=REFUNDED records the
-- payment state, but no partial-refund amount, refund reference, or refund ledger
-- is modeled. A refund does not reverse fulfilment or alter planting records.

BEGIN;

CREATE TYPE "TreeOrderStatus" AS ENUM (
  'PENDING_PAYMENT',
  'PAID',
  'PROCESSING',
  'COMPLETED',
  'CANCELLED'
);

CREATE TYPE "PaymentStatus" AS ENUM (
  'PENDING',
  'SUCCESSFUL',
  'FAILED',
  'REFUNDED'
);

CREATE TYPE "LocationReviewStatus" AS ENUM (
  'PENDING',
  'APPROVED',
  'REJECTED'
);

CREATE TYPE "OrderFulfilmentStatus" AS ENUM (
  'NOT_SCHEDULED',
  'SCHEDULED',
  'PLANTED',
  'VERIFICATION_PENDING'
);

CREATE TYPE "PlantingVerificationStatus" AS ENUM (
  'NOT_STARTED',
  'PENDING',
  'VERIFIED',
  'REJECTED'
);

ALTER TABLE "TreeSpecies"
  ADD COLUMN "priceKobo" INTEGER,
  ADD COLUMN "isPublished" BOOLEAN NOT NULL DEFAULT false,
  ADD CONSTRAINT "TreeSpecies_priceKobo_nonnegative_check"
    CHECK ("priceKobo" IS NULL OR "priceKobo" >= 0);

CREATE INDEX "TreeSpecies_isPublished_isActive_name_idx"
  ON "TreeSpecies" ("isPublished", "isActive", "name");

CREATE TABLE "TreeOrder" (
  "id" TEXT NOT NULL,
  "reference" TEXT NOT NULL,
  "customerName" TEXT NOT NULL,
  "customerEmail" TEXT NOT NULL,
  "customerPhone" TEXT NOT NULL,
  "requestedLocation" TEXT NOT NULL,
  "locationDirections" TEXT,
  "status" "TreeOrderStatus" NOT NULL DEFAULT 'PENDING_PAYMENT',
  "paymentStatus" "PaymentStatus" NOT NULL DEFAULT 'PENDING',
  "locationReviewStatus" "LocationReviewStatus" NOT NULL DEFAULT 'PENDING',
  "fulfilmentStatus" "OrderFulfilmentStatus" NOT NULL DEFAULT 'NOT_SCHEDULED',
  "plantingVerificationStatus" "PlantingVerificationStatus" NOT NULL DEFAULT 'NOT_STARTED',
  "totalAmountKobo" INTEGER NOT NULL,
  "currency" TEXT NOT NULL DEFAULT 'NGN',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "TreeOrder_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "TreeOrder_reference_key" UNIQUE ("reference"),
  CONSTRAINT "TreeOrder_totalAmountKobo_positive_check"
    CHECK ("totalAmountKobo" > 0),
  CONSTRAINT "TreeOrder_currency_ngn_check"
    CHECK ("currency" = 'NGN')
);

CREATE INDEX "TreeOrder_status_createdAt_idx"
  ON "TreeOrder" ("status", "createdAt");
CREATE INDEX "TreeOrder_paymentStatus_createdAt_idx"
  ON "TreeOrder" ("paymentStatus", "createdAt");
CREATE INDEX "TreeOrder_locationReviewStatus_createdAt_idx"
  ON "TreeOrder" ("locationReviewStatus", "createdAt");
CREATE INDEX "TreeOrder_fulfilmentStatus_createdAt_idx"
  ON "TreeOrder" ("fulfilmentStatus", "createdAt");
CREATE INDEX "TreeOrder_plantingVerificationStatus_createdAt_idx"
  ON "TreeOrder" ("plantingVerificationStatus", "createdAt");

CREATE TABLE "TreeOrderItem" (
  "id" TEXT NOT NULL,
  "orderId" TEXT NOT NULL,
  "speciesId" TEXT NOT NULL,
  "speciesName" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL,
  "unitPriceKobo" INTEGER NOT NULL,
  "lineTotalKobo" INTEGER NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "TreeOrderItem_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "TreeOrderItem_quantity_positive_check"
    CHECK ("quantity" > 0),
  CONSTRAINT "TreeOrderItem_unitPriceKobo_nonnegative_check"
    CHECK ("unitPriceKobo" >= 0),
  CONSTRAINT "TreeOrderItem_lineTotalKobo_check"
    CHECK (
      "lineTotalKobo" >= 0 AND
      "lineTotalKobo"::BIGINT =
        "quantity"::BIGINT * "unitPriceKobo"::BIGINT
    ),
  CONSTRAINT "TreeOrderItem_orderId_fkey"
    FOREIGN KEY ("orderId") REFERENCES "TreeOrder"("id")
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "TreeOrderItem_speciesId_fkey"
    FOREIGN KEY ("speciesId") REFERENCES "TreeSpecies"("id")
    ON DELETE RESTRICT ON UPDATE CASCADE
);

CREATE INDEX "TreeOrderItem_orderId_idx" ON "TreeOrderItem" ("orderId");
CREATE INDEX "TreeOrderItem_speciesId_idx" ON "TreeOrderItem" ("speciesId");

CREATE TABLE "TreeDonation" (
  "id" TEXT NOT NULL,
  "reference" TEXT NOT NULL,
  "donorName" TEXT NOT NULL,
  "donorEmail" TEXT NOT NULL,
  "donorPhone" TEXT NOT NULL,
  "speciesId" TEXT NOT NULL,
  "speciesName" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL,
  "unitPriceKobo" INTEGER NOT NULL,
  "totalAmountKobo" INTEGER NOT NULL,
  "currency" TEXT NOT NULL DEFAULT 'NGN',
  "paymentStatus" "PaymentStatus" NOT NULL DEFAULT 'PENDING',
  "plantingVerificationStatus" "PlantingVerificationStatus" NOT NULL DEFAULT 'NOT_STARTED',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "TreeDonation_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "TreeDonation_reference_key" UNIQUE ("reference"),
  CONSTRAINT "TreeDonation_quantity_positive_check"
    CHECK ("quantity" > 0),
  CONSTRAINT "TreeDonation_unitPriceKobo_nonnegative_check"
    CHECK ("unitPriceKobo" >= 0),
  CONSTRAINT "TreeDonation_totalAmountKobo_check"
    CHECK (
      "totalAmountKobo" > 0 AND
      "totalAmountKobo"::BIGINT =
        "quantity"::BIGINT * "unitPriceKobo"::BIGINT
    ),
  CONSTRAINT "TreeDonation_currency_ngn_check"
    CHECK ("currency" = 'NGN'),
  CONSTRAINT "TreeDonation_speciesId_fkey"
    FOREIGN KEY ("speciesId") REFERENCES "TreeSpecies"("id")
    ON DELETE RESTRICT ON UPDATE CASCADE
);

CREATE INDEX "TreeDonation_paymentStatus_createdAt_idx"
  ON "TreeDonation" ("paymentStatus", "createdAt");
CREATE INDEX "TreeDonation_plantingVerificationStatus_createdAt_idx"
  ON "TreeDonation" ("plantingVerificationStatus", "createdAt");
CREATE INDEX "TreeDonation_speciesId_createdAt_idx"
  ON "TreeDonation" ("speciesId", "createdAt");

CREATE TABLE "PaymentTransaction" (
  "id" TEXT NOT NULL,
  "orderId" TEXT,
  "donationId" TEXT,
  "reference" TEXT NOT NULL,
  "paystackTransactionId" BIGINT,
  "amountKobo" INTEGER NOT NULL,
  "currency" TEXT NOT NULL DEFAULT 'NGN',
  "status" "PaymentStatus" NOT NULL DEFAULT 'PENDING',
  "verifiedAt" TIMESTAMP(3),
  "webhookProcessedAt" TIMESTAMP(3),
  "appliedAt" TIMESTAMP(3),
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "PaymentTransaction_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "PaymentTransaction_reference_key" UNIQUE ("reference"),
  CONSTRAINT "PaymentTransaction_paystackTransactionId_key"
    UNIQUE ("paystackTransactionId"),
  CONSTRAINT "PaymentTransaction_amountKobo_positive_check"
    CHECK ("amountKobo" > 0),
  CONSTRAINT "PaymentTransaction_currency_ngn_check"
    CHECK ("currency" = 'NGN'),
  CONSTRAINT "PaymentTransaction_applied_requires_verified_payment_check"
    CHECK (
      "appliedAt" IS NULL OR
      (
        "status" IN ('SUCCESSFUL', 'REFUNDED') AND
        "verifiedAt" IS NOT NULL
      )
    ),
  CONSTRAINT "PaymentTransaction_exactly_one_owner_check"
    CHECK (("orderId" IS NULL) <> ("donationId" IS NULL)),
  CONSTRAINT "PaymentTransaction_orderId_fkey"
    FOREIGN KEY ("orderId") REFERENCES "TreeOrder"("id")
    ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT "PaymentTransaction_donationId_fkey"
    FOREIGN KEY ("donationId") REFERENCES "TreeDonation"("id")
    ON DELETE RESTRICT ON UPDATE CASCADE
);

CREATE INDEX "PaymentTransaction_orderId_status_createdAt_idx"
  ON "PaymentTransaction" ("orderId", "status", "createdAt");
CREATE INDEX "PaymentTransaction_donationId_status_createdAt_idx"
  ON "PaymentTransaction" ("donationId", "status", "createdAt");
CREATE INDEX "PaymentTransaction_status_createdAt_idx"
  ON "PaymentTransaction" ("status", "createdAt");

-- A commerce fulfilment may be backed by multiple planting batches, but each
-- planting record can be attributed to at most one order or donation.
ALTER TABLE "PlantingRecord"
  ADD COLUMN "treeOrderId" TEXT,
  ADD COLUMN "treeDonationId" TEXT,
  ADD CONSTRAINT "PlantingRecord_commerce_owner_check"
    CHECK ("treeOrderId" IS NULL OR "treeDonationId" IS NULL),
  ADD CONSTRAINT "PlantingRecord_treeOrderId_fkey"
    FOREIGN KEY ("treeOrderId") REFERENCES "TreeOrder"("id")
    ON DELETE RESTRICT ON UPDATE CASCADE,
  ADD CONSTRAINT "PlantingRecord_treeDonationId_fkey"
    FOREIGN KEY ("treeDonationId") REFERENCES "TreeDonation"("id")
    ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE INDEX "PlantingRecord_treeOrderId_idx"
  ON "PlantingRecord" ("treeOrderId");
CREATE INDEX "PlantingRecord_treeDonationId_idx"
  ON "PlantingRecord" ("treeDonationId");

-- Each order/donation can have at most one payment applied to its paid state.
-- The appliedAt marker remains set after a full refund, preserving the original
-- applied charge and preventing a second charge from being applied.
-- Other verified successful Paystack charges remain recordable for reconciliation/refund.
CREATE UNIQUE INDEX "PaymentTransaction_one_applied_payment_per_order_key"
  ON "PaymentTransaction" ("orderId")
  WHERE "orderId" IS NOT NULL AND "appliedAt" IS NOT NULL;
CREATE UNIQUE INDEX "PaymentTransaction_one_applied_payment_per_donation_key"
  ON "PaymentTransaction" ("donationId")
  WHERE "donationId" IS NOT NULL AND "appliedAt" IS NOT NULL;

COMMIT;
